// --- Звук (WebAudio; молча отключается, если аудио недоступно) ---
let audioCtx = null;
function beep(freq, dur, type = "square", vol = 0.04) {
  try {
    audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();
    const o = audioCtx.createOscillator();
    const g = audioCtx.createGain();
    o.type = type; o.frequency.value = freq; g.gain.value = vol;
    o.connect(g); g.connect(audioCtx.destination);
    o.start();
    g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + dur);
    o.stop(audioCtx.currentTime + dur);
  } catch (_) {}
}

function resetGame() {
  state.score = 0; state.level = 1; state.lives = 3; state.invuln = 0;
  state.ship.x = W / 2; state.ship.y = H - 80;
  state.bullets = []; state.asteroids = []; state.particles = [];
  state.shake = 0; state.spawnTimer = 0; state.over = false; state.running = true;
}
function startGame() { resetGame(); }

// --- Астероид ---
function spawnAsteroid() {
  const levelScale = 1 + (state.level - 1) * 0.18;
  const size = 18 + Math.random() * 26;
  const speed = (0.6 + Math.random() * 1.4) * levelScale;
  const r = size;
  let x, y, vx, vy;
  if (Math.random() < 0.6) {           // сверху
    x = r + Math.random() * (W - 2 * r); y = -r;
    vy = speed * (0.6 + Math.random() * 0.8);
    vx = (Math.random() - 0.5) * speed;
  } else {                             // с боков
    x = Math.random() < 0.5 ? -r : W + r;
    y = r + Math.random() * (H * 0.6);
    vx = (x < W / 2 ? 1 : -1) * speed;
    vy = (Math.random() - 0.5) * speed * 0.7;
  }
  const shape = [];
  const points = 9 + Math.floor(Math.random() * 5);
  for (let i = 0; i < points; i++) shape.push(r * (0.7 + Math.random() * 0.45));
  state.asteroids.push({
    x, y, vx, vy, r, size,
    rot: Math.random() * Math.PI * 2,
    rotSpeed: (Math.random() - 0.5) * 0.06,
    shape,
    split: size > 34,
  });
}

function splitAsteroid(a) {
  for (let i = 0; i < 2; i++) {
    const nr = a.r * 0.55;
    state.asteroids.push({
      x: a.x + (Math.random() - 0.5) * a.r,
      y: a.y + (Math.random() - 0.5) * a.r,
      vx: a.vx + (Math.random() - 0.5) * 2.2,
      vy: a.vy + (Math.random() - 0.5) * 2.2,
      r: nr, size: nr * 1.6,
      rot: Math.random() * Math.PI * 2,
      rotSpeed: (Math.random() - 0.5) * 0.1,
      shape: a.shape.map(s => s * 0.55),
      split: false,
    });
  }
}

