function explode(x, y, color, n) {
  for (let i = 0; i < n; i++) {
    const ang = Math.random() * Math.PI * 2;
    const sp = 40 + Math.random() * 160;
    state.particles.push({
      x, y,
      vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp,
      life: 0.4 + Math.random() * 0.5, max: 0.9,
      size: 1.5 + Math.random() * 2.5, color,
    });
  }
}

function bulletHit(b, a) {
  state.score += a.split ? 20 : 40;
  if (a.split) splitAsteroid(a);
  explode(a.x, a.y, "#ffd27a", a.split ? 22 : 12);
  explode(a.x, a.y, "#ff8f5e", 8);
  beep(220, 0.12, "sawtooth", 0.05);
  state.shake = Math.min(14, state.shake + 4);
  const ai = state.asteroids.indexOf(a);
  if (ai !== -1) state.asteroids.splice(ai, 1);
  const bi = state.bullets.indexOf(b);
  if (bi !== -1) state.bullets.splice(bi, 1);
}

function shipHit(a) {
  state.lives--; state.invuln = 2.2;
  explode(state.ship.x, state.ship.y, "#7fd4ff", 30);
  explode(state.ship.x, state.ship.y, "#ffffff", 12);
  beep(90, 0.5, "sawtooth", 0.08);
  state.shake = 18;
  const ai = state.asteroids.indexOf(a);
  if (ai !== -1) state.asteroids.splice(ai, 1);
