// --- Обновление логики ---
function update(dt) {
  for (const s of state.stars) {      // параллакс звёзд
    s.y += s.speed * 60 * dt;
    s.twinkle += dt * 3;
    if (s.y > H) { s.y = -2; s.x = Math.random() * W; }
  }
  if (!state.running || state.over) return;

  // корабль
  const acc = 420, maxV = 300, drag = 0.92;
  let vx = state.ship.vx || 0, vy = state.ship.vy || 0;
  if (keys["ArrowLeft"] || keys["KeyA"]) vx -= acc * dt;
  if (keys["ArrowRight"] || keys["KeyD"]) vx += acc * dt;
  if (keys["ArrowUp"] || keys["KeyW"]) vy -= acc * dt;
  if (keys["ArrowDown"] || keys["KeyS"]) vy += acc * dt;
  const sp = Math.hypot(vx, vy);
  if (sp > maxV) { vx *= maxV / sp; vy *= maxV / sp; }
  vx *= drag; vy *= drag;
  state.ship.vx = vx; state.ship.vy = vy;
  state.ship.x = Math.max(state.ship.r, Math.min(W - state.ship.r, state.ship.x + vx * dt));
  state.ship.y = Math.max(state.ship.r, Math.min(H - state.ship.r, state.ship.y + vy * dt));

  // выстрелы
  state.shootTimer = (state.shootTimer || 0) - dt;
  if ((keys["Space"] || keys["KeyJ"]) && state.shootTimer <= 0) {
    state.shootTimer = 0.22;
    state.bullets.push({ x: state.ship.x, y: state.ship.y - 18, vy: -620 });
    beep(880, 0.06, "square", 0.02);
  }
  for (const b of state.bullets) b.y += b.vy * dt;
  state.bullets = state.bullets.filter(b => b.y > -20);

  // спавн астероидов
