  const interval = Math.max(0.35, 1.6 - state.level * 0.12);
  if (state.spawnTimer <= 0) {
    state.spawnTimer = interval;
    spawnAsteroid();
    if (state.level >= 3 && Math.random() < 0.3) spawnAsteroid();
  }

  // движение астероидов
  for (const a of state.asteroids) {
    a.x += a.vx * 60 * dt;
    a.y += a.vy * 60 * dt;
    a.rot += a.rotSpeed;
  }
  state.asteroids = state.asteroids.filter(a =>
    a.x > -60 && a.x < W + 60 && a.y > -60 && a.y < H + 60);

  // уровень растёт каждые 1000 очков
  state.level = 1 + Math.floor(state.score / 1000);

  // коллизии пуля-астероид
  for (const b of [...state.bullets]) {
    for (const a of [...state.asteroids]) {
      const dx = b.x - a.x, dy = b.y - a.y;
      if (dx * dx + dy * dy < (a.r + 4) * (a.r + 4)) { bulletHit(b, a); break; }
