  ctx.lineTo(x - 14, y + 14);
  ctx.lineTo(x - 5, y + 8);
  ctx.lineTo(x, y + 14);
  ctx.lineTo(x + 5, y + 8);
  ctx.lineTo(x + 14, y + 14);
  ctx.closePath();
  const grad = ctx.createLinearGradient(x, y - 22, x, y + 14);
  grad.addColorStop(0, "#a8e6ff");
  grad.addColorStop(1, "#4a7dff");
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.strokeStyle = "#dff4ff";
  ctx.lineWidth = 1.5;
  ctx.stroke();
