for (let i = 0; i < 140; i++) {
  state.stars.push({
    x: Math.random() * W, y: Math.random() * H,
    size: Math.random() < 0.85 ? 1 : 2,
    speed: 0.4 + Math.random() * 1.6,
    twinkle: Math.random() * Math.PI * 2,
  });
