+    box-shadow: 0 0 60px rgba(80, 120, 255, 0.15);
+    max-width: 100vw;
+    max-height: 100vh;
+  }
+</style>
+</head>
+<body>
+<canvas id="game" width="800" height="600"></canvas>
+<script>
+"use strict";
+
+const canvas = document.getElementById("game");
+const ctx = canvas.getContext("2d");
+const W = canvas.width, H = canvas.height;
+
+// --- Состояние игры ---
+const state = {
+  running: false, over: false, score: 0, level: 1, lives: 3,
+  invuln: 0, ship: { x: W / 2, y: H - 80, r: 14 },
+  bullets: [], asteroids: [], particles: [], stars: [],
+  spawnTimer: 0, shake: 0,
+};
+const keys = {};
+
+// --- Управление ---
+window.addEventListener("keydown", e => {
+  keys[e.code] = true;
+  if (e.code === "Space") e.preventDefault();
+  if (e.code === "KeyR" && state.over) resetGame();
+  if (e.code === "Enter" && !state.running && !state.over) startGame();
+});
+window.addEventListener("keyup", e => { keys[e.code] = false; });
+canvas.addEventListener("click", () => {
+  if (state.over) resetGame();
+  else if (!state.running) startGame();
+});
+
+// --- Фон: звёзды ---
+for (let i = 0; i < 140; i++) {
+  state.stars.push({
+    x: Math.random() * W, y: Math.random() * H,
+    size: Math.random() < 0.85 ? 1 : 2,
+    speed: 0.4 + Math.random() * 1.6,
+    twinkle: Math.random() * Math.PI * 2,
+  });
+}
+
+// --- Звук (WebAudio; молча отключается, если аудио недоступно) ---
+let audioCtx = null;
+function beep(freq, dur, type = "square", vol = 0.04) {
+  try {
+    audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();
+    const o = audioCtx.createOscillator();
+    const g = audioCtx.createGain();
+    o.type = type; o.frequency.value = freq; g.gain.value = vol;
+    o.connect(g); g.connect(audioCtx.destination);
+    o.start();
+    g.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + dur);
+    o.stop(audioCtx.currentTime + dur);
+  } catch (_) {}
+}
+
+function resetGame() {
+  state.score = 0; state.level = 1; state.lives = 3; state.invuln = 0;
+  state.ship.x = W / 2; state.ship.y = H - 80;
+  state.bullets = []; state.asteroids = []; state.particles = [];
+  state.shake = 0; state.spawnTimer = 0; state.over = false; state.running = true;
+}
+function startGame() { resetGame(); }
+
+// --- Астероид ---
+function spawnAsteroid() {
+  const levelScale = 1 + (state.level - 1) * 0.18;
+  const size = 18 + Math.random() * 26;
+  const speed = (0.6 + Math.random() * 1.4) * levelScale;
+  const r = size;
+  let x, y, vx, vy;
+  if (Math.random() < 0.6) {           // сверху
+    x = r + Math.random() * (W - 2 * r); y = -r;
+    vy = speed * (0.6 + Math.random() * 0.8);
+    vx = (Math.random() - 0.5) * speed;
+  } else {                             // с боков
+    x = Math.random() < 0.5 ? -r : W + r;
+    y = r + Math.random() * (H * 0.6);
+    vx = (x < W / 2 ? 1 : -1) * speed;
+    vy = (Math.random() - 0.5) * speed * 0.7;
+  }
+  const shape = [];
+  const points = 9 + Math.floor(Math.random() * 5);
+  for (let i = 0; i < points; i++) shape.push(r * (0.7 + Math.random() * 0.45));
+  state.asteroids.push({
+    x, y, vx, vy, r, size,
+    rot: Math.random() * Math.PI * 2,
+    rotSpeed: (Math.random() - 0.5) * 0.06,
+    shape,
+    split: size > 34,
+  });
+}
+
+function splitAsteroid(a) {
+  for (let i = 0; i < 2; i++) {
+    const nr = a.r * 0.55;
+    state.asteroids.push({
+      x: a.x + (Math.random() - 0.5) * a.r,
+      y: a.y + (Math.random() - 0.5) * a.r,
+      vx: a.vx + (Math.random() - 0.5) * 2.2,
+      vy: a.vy + (Math.random() - 0.5) * 2.2,
+      r: nr, size: nr * 1.6,
+      rot: Math.random() * Math.PI * 2,
+      rotSpeed: (Math.random() - 0.5) * 0.1,
+      shape: a.shape.map(s => s * 0.55),
+      split: false,
+    });
+  }
+}
+
+// --- Частицы взрыва ---
+function explode(x, y, color, n) {
+  for (let i = 0; i < n; i++) {
+    const ang = Math.random() * Math.PI * 2;
+    const sp = 40 + Math.random() * 160;
+    state.particles.push({
+      x, y,
+      vx: Math.cos(ang) * sp, vy: Math.sin(ang) * sp,
+      life: 0.4 + Math.random() * 0.5, max: 0.9,
+      size: 1.5 + Math.random() * 2.5, color,
+    });
+  }
+}
+
+function bulletHit(b, a) {
+  state.score += a.split ? 20 : 40;
+  if (a.split) splitAsteroid(a);
+  explode(a.x, a.y, "#ffd27a", a.split ? 22 : 12);
+  explode(a.x, a.y, "#ff8f5e", 8);
+  beep(220, 0.12, "sawtooth", 0.05);
+  state.shake = Math.min(14, state.shake + 4);
+  const ai = state.asteroids.indexOf(a);
+  if (ai !== -1) state.asteroids.splice(ai, 1);
+  const bi = state.bullets.indexOf(b);
+  if (bi !== -1) state.bullets.splice(bi, 1);
+}
+
+function shipHit(a) {
+  state.lives--; state.invuln = 2.2;
+  explode(state.ship.x, state.ship.y, "#7fd4ff", 30);
+  explode(state.ship.x, state.ship.y, "#ffffff", 12);
+  beep(90, 0.5, "sawtooth", 0.08);
+  state.shake = 18;
+  const ai = state.asteroids.indexOf(a);
+  if (ai !== -1) state.asteroids.splice(ai, 1);
+  if (state.lives <= 0) state.over = true;
+}
+
+// --- Обновление логики ---
+function update(dt) {
+  for (const s of state.stars) {      // параллакс звёзд
+    s.y += s.speed * 60 * dt;
+    s.twinkle += dt * 3;
+    if (s.y > H) { s.y = -2; s.x = Math.random() * W; }
+  }
+  if (!state.running || state.over) return;
+
+  // корабль
+  const acc = 420, maxV = 300, drag = 0.92;
+  let vx = state.ship.vx || 0, vy = state.ship.vy || 0;
+  if (keys["ArrowLeft"] || keys["KeyA"]) vx -= acc * dt;
+  if (keys["ArrowRight"] || keys["KeyD"]) vx += acc * dt;
+  if (keys["ArrowUp"] || keys["KeyW"]) vy -= acc * dt;
+  if (keys["ArrowDown"] || keys["KeyS"]) vy += acc * dt;
+  const sp = Math.hypot(vx, vy);
+  if (sp > maxV) { vx *= maxV / sp; vy *= maxV / sp; }
+  vx *= drag; vy *= drag;
+  state.ship.vx = vx; state.ship.vy = vy;
+  state.ship.x = Math.max(state.ship.r, Math.min(W - state.ship.r, state.ship.x + vx * dt));
+  state.ship.y = Math.max(state.ship.r, Math.min(H - state.ship.r, state.ship.y + vy * dt));
+
+  // выстрелы
+  state.shootTimer = (state.shootTimer || 0) - dt;
+  if ((keys["Space"] || keys["KeyJ"]) && state.shootTimer <= 0) {
+    state.shootTimer = 0.22;
+    state.bullets.push({ x: state.ship.x, y: state.ship.y - 18, vy: -620 });
+    beep(880, 0.06, "square", 0.02);
+  }
+  for (const b of state.bullets) b.y += b.vy * dt;
+  state.bullets = state.bullets.filter(b => b.y > -20);
+
+  // спавн астероидов
+  state.spawnTimer -= dt;
+  const interval = Math.max(0.35, 1.6 - state.level * 0.12);
+  if (state.spawnTimer <= 0) {
+    state.spawnTimer = interval;
+    spawnAsteroid();
+    if (state.level >= 3 && Math.random() < 0.3) spawnAsteroid();
+  }
+
+  // движение астероидов
+  for (const a of state.asteroids) {
+    a.x += a.vx * 60 * dt;
+    a.y += a.vy * 60 * dt;
+    a.rot += a.rotSpeed;
+  }
+  state.asteroids = state.asteroids.filter(a =>
+    a.x > -60 && a.x < W + 60 && a.y > -60 && a.y < H + 60);
+
+  // уровень растёт каждые 1000 очков
+  state.level = 1 + Math.floor(state.score / 1000);
+
+  // коллизии пуля-астероид
+  for (const b of [...state.bullets]) {
+    for (const a of [...state.asteroids]) {
+      const dx = b.x - a.x, dy = b.y - a.y;
+      if (dx * dx + dy * dy < (a.r + 4) * (a.r + 4)) { bulletHit(b, a); break; }
+    }
+  }
+
+  // коллизии корабль-астероид
+  if (state.invuln > 0) state.invuln -= dt;
+  if (state.invuln <= 0) {
+    for (const a of [...state.asteroids]) {
+      const dx = state.ship.x - a.x, dy = state.ship.y - a.y;
+      if (dx * dx + dy * dy < (a.r + state.ship.r) * (a.r + state.ship.r)) {
+        shipHit(a);
+        break;
+      }
+    }
+  }
+
+  // частицы
+  for (const p of state.particles) {
+    p.x += p.vx * dt; p.y += p.vy * dt;
+    p.vx *= 0.96; p.vy *= 0.96;
+    p.life -= dt;
+  }
+  state.particles = state.particles.filter(p => p.life > 0);
+  state.shake *= 0.9;
+}
+
+// --- Отрисовка ---
+function drawShip() {
+  const { x, y } = state.ship;
+  const blink = state.invuln > 0 && Math.floor(state.invuln * 12) % 2 === 0;
+  if (blink) return;
+  ctx.beginPath();
+  ctx.moveTo(x, y - 22);
+  ctx.lineTo(x - 14, y + 14);
+  ctx.lineTo(x - 5, y + 8);
+  ctx.lineTo(x, y + 14);
+  ctx.lineTo(x + 5, y + 8);
+  ctx.lineTo(x + 14, y + 14);
+  ctx.closePath();
+  const grad = ctx.createLinearGradient(x, y - 22, x, y + 14);
+  grad.addColorStop(0, "#a8e6ff");
+  grad.addColorStop(1, "#4a7dff");
+  ctx.fillStyle = grad;
+  ctx.fill();
+  ctx.strokeStyle = "#dff4ff";
+  ctx.lineWidth = 1.5;
+  ctx.stroke();
+  const flicker = 6 + Math.random() * 6;   // двигатель
+  ctx.beginPath();
+  ctx.moveTo(x - 5, y + 12);
+  ctx.lineTo(x, y + 12 + flicker);
+  ctx.lineTo(x + 5, y + 12);
+  ctx.fillStyle = "rgba(120, 200, 255, 0.9)";
+  ctx.fill();
+}
+
+function drawAsteroid(a) {
+  ctx.beginPath();
+  const n = a.shape.length;
+  for (let i = 0; i < n; i++) {
+    const ang = a.rot + (i / n) * Math.PI * 2;
+    const px = a.x + Math.cos(ang) * a.shape[i];
+    const py = a.y + Math.sin(ang) * a.shape[i];
+    if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
+  }
+  ctx.closePath();
+  const grad = ctx.createRadialGradient(a.x - a.r * 0.3, a.y - a.r * 0.3, a.r * 0.2, a.x, a.y, a.r);
+  grad.addColorStop(0, "#8a7a66");
+  grad.addColorStop(1, "#3a3128");
+  ctx.fillStyle = grad;
+  ctx.fill();
+  ctx.strokeStyle = "#5d4f3e";
+  ctx.lineWidth = 2;
+  ctx.stroke();
+}
+
+function draw() {
+  ctx.save();
+  if (state.shake > 0.5) {
+    ctx.translate((Math.random() - 0.5) * state.shake, (Math.random() - 0.5) * state.shake);
+  }
+  for (const s of state.stars) {
+    ctx.globalAlpha = 0.4 + 0.6 * Math.abs(Math.sin(s.twinkle));
+    ctx.fillStyle = "#cfe0ff";
+    ctx.fillRect(s.x, s.y, s.size, s.size);
+  }
+  ctx.globalAlpha = 1;
+  for (const p of state.particles) {
+    ctx.globalAlpha = Math.max(0, p.life / p.max);
+    ctx.fillStyle = p.color;
+    ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
+  }
+  ctx.globalAlpha = 1;
+  for (const a of state.asteroids) drawAsteroid(a);
+  ctx.fillStyle = "#ffd27a";
+  for (const b of state.bullets) {
+    ctx.beginPath();
+    ctx.arc(b.x, b.y, 3.5, 0, Math.PI * 2);
+    ctx.fill();
+  }
+  if (state.running && !state.over) drawShip();
+  ctx.restore();
+
+  // HUD
+  ctx.fillStyle = "#dfe6ff";
+  ctx.font = "bold 20px system-ui, sans-serif";
+  ctx.textAlign = "left";
+  ctx.fillText(`СЧЁТ: ${state.score}`, 16, 32);
+  ctx.textAlign = "right";
+  ctx.fillText(`УРОВЕНЬ: ${state.level}`, W - 16, 32);
+  ctx.fillStyle = "#ff5e7a";
+  ctx.font = "22px system-ui, sans-serif";
+  ctx.fillText("♥".repeat(Math.max(0, state.lives)), W - 16, 58);
+
+  if (!state.running) {
+    ctx.fillStyle = "rgba(5, 8, 20, 0.72)";
+    ctx.fillRect(0, 0, W, H);
+    ctx.textAlign = "center";
+    ctx.fillStyle = "#a8e6ff";
+    ctx.font = "bold 42px system-ui, sans-serif";
+    ctx.fillText("КОСМИЧЕСКИЙ РУБЕЖ", W / 2, H / 2 - 70);
+    ctx.fillStyle = "#dfe6ff";
+    ctx.font = "18px system-ui, sans-serif";
+    ctx.fillText("← → ↑ ↓ или WASD — движение, ПРОБЕЛ — огонь", W / 2, H / 2 - 20);
+    ctx.fillStyle = "#7fd4ff";
+    ctx.font = "bold 22px system-ui, sans-serif";
+    ctx.fillText(state.over ? "ИГРА ОКОНЧЕНА" : "НАЖМИ ENTER ИЛИ КЛИКНИ, ЧТОБЫ НАЧАТЬ", W / 2, H / 2 + 24);
+    ctx.fillStyle = "#9aa5c9";
+    ctx.font = "16px system-ui, sans-serif";
+    if (state.over) {
+      ctx.fillText(`Твой счёт: ${state.score}  ·  R — сыграть ещё раз`, W / 2, H / 2 + 58);
+    }
+  }
+}
+
+// --- Главный цикл ---
+let last = performance.now();
+function loop(now) {
+  const dt = Math.min(0.05, (now - last) / 1000);
+  last = now;
+  update(dt);
+  draw();
+  requestAnimationFrame(loop);
+}
+requestAnimationFrame(loop);
+</script>
+</body>
+</html>
